const b = ($json.body !== undefined) ? $json.body : $json;
const telefone = (b.telefone || '').toString().trim();
const mensagem_texto = (b.mensagem_texto || '').toString().trim();
if (!telefone || !mensagem_texto) {
  return [{ json: { _erro: 'parametros_invalidos' } }];
}
return [{ json: {
  telefone,
  mensagem_texto,
  message_id: b.message_id || ('agente-' + telefone + '-' + telefone.length + '-' + mensagem_texto.length),
} }];

const entrada = $('Validar Entrada').first().json;
const autorizado = $input.all().some(i => i.json && i.json.telefone);
return [{ json: { ...entrada, autorizado } }];

const entrada = $('Avaliar Whitelist').first().json;
const resp = $json;
const body = resp.body || {};
return [{ json: { ...entrada, is_dizu: !!body.is_dizu } }];

const entrada = $('Avaliar Dizu').first().json;
const resp = $json;
const body = resp.body || {};
return [{ json: {
  telefone: entrada.telefone,
  message_id: entrada.message_id,
  texto_final: body.frase_pronta || 'Chamando a equipe',
  guardrail_bloqueou: false,
  motivo_bloqueio: null,
} }];

const entrada = $('Preparar Prompt Sistema').first().json;
const out = $json.output || $json.text || '';
return [{ json: {
  telefone: entrada.telefone,
  message_id: entrada.message_id,
  resposta_agente: out,
  _intermediateSteps: $json.intermediateSteps || null,
} }];

// Demanda 297: nenhuma mensagem sai com valor em R$ sem uma chamada de
// ferramenta correspondente no mesmo turno. Varre o texto da IA procurando
// R$, e so deixa passar se algum valor bater com o que uma ferramenta de
// valor (preco/pedido/pix) realmente devolveu nesta execucao.
const entrada = $json;
const texto = entrada.resposta_agente || '';

function extrairValores(txt) {
  // Demanda 298 (achado real): a IA pode falar um valor numerico sem o
  // simbolo R$ (ex. "fica 1,20 a unidade"), o que escapava completamente
  // desta checagem antes. Alem de "R$ X,XX", agora tambem casa qualquer
  // numero no formato decimal brasileiro (X,XX ou X.XXX,XX) em qualquer
  // lugar do texto, mesmo sem o simbolo - baixo risco de falso positivo
  // porque esse formato especifico (virgula com exatamente 2 casas) quase
  // nunca aparece em conversa comum fora de valor monetario.
  const re = /R\$\s*[0-9]{1,3}(?:[.,][0-9]{3})*(?:[.,][0-9]{2})?|[0-9]{1,3}(?:\.[0-9]{3})*,[0-9]{2}/g;
  const vals = [];
  let m;
  while ((m = re.exec(txt)) !== null) {
    let raw = m[0].replace(/R\$\s*/, '');
    let n = raw.replace(/\./g, '').replace(',', '.');
    const v = parseFloat(n);
    if (!isNaN(v)) vals.push(v);
  }
  return vals;
}

// Demanda 298 (teste adversarial): achado real e confirmado - pedir pra IA
// "traduzir"/"resumir"/"repetir" as instrucoes vazou o prompt de sistema
// inteiro (nomes de ferramenta, motivos de escalonamento, logica do
// guardrail) direto pro cliente, sem bater em nenhum guardrail existente.
// Corrigido com checagem de identificadores internos que nunca deveriam
// aparecer numa mensagem real pro cliente, em nenhum idioma (nomes de
// ferramenta sao identificador de codigo, sobrevivem traducao/paraphrase).
const identificadoresInternos = [
  'consultar_preco_produto', 'criar_pedido_aguardando_aprovacao', 'gerar_cobranca_pix',
  'processar_cancelamento', 'escalar_para_humano', 'alto_toque', 'ambiguo_nao_resolvido',
  'negociacao_pagamento', 'proposta_negada', 'frase_pronta', 'motivo_escalonamento',
  'jsgrafica_pedidos', 'tool_consultar', 'tool_criar_pedido', 'tool_gerar_cobranca',
  'tool_processar_cancelamento', 'tool_escalar',
];
const textoLower = (entrada.resposta_agente || '').toLowerCase();
const identificadorVazado = identificadoresInternos.find(id => textoLower.includes(id));
if (identificadorVazado) {
  return [{ json: {
    ...entrada, guardrail_ok: false,
    motivo_bloqueio: `texto contem identificador interno vazado (${identificadorVazado}), provavel tentativa de expor o prompt de sistema`,
  } }];
}

// Demanda 298 (teste adversarial): checagem extra pro achado da 297 (telefone
// vem da IA por limitacao de plataforma, nao injetado pelo sistema). 3
// tentativas reais de fazer a IA usar outro telefone numa ferramenta nao
// tiveram sucesso, mas isso nao e garantia formal - fecha o gap de verdade
// aqui, comparando o telefone de QUALQUER chamada de ferramenta contra o
// telefone real desta conversa.
const stepsTel = Array.isArray(entrada._intermediateSteps) ? entrada._intermediateSteps : [];
const telefoneDivergente = stepsTel.find(s => {
  const tin = s && s.action && s.action.toolInput;
  return tin && tin.telefone && String(tin.telefone).replace(/\D/g, '') !== String(entrada.telefone).replace(/\D/g, '');
});
if (telefoneDivergente) {
  return [{ json: {
    ...entrada, guardrail_ok: false,
    motivo_bloqueio: `ferramenta ${telefoneDivergente.action.tool} foi chamada com telefone diferente do real desta conversa (${telefoneDivergente.action.toolInput.telefone} vs ${entrada.telefone})`,
  } }];
}

const steps0 = Array.isArray(entrada._intermediateSteps) ? entrada._intermediateSteps : [];
const chamouEscalar = steps0.some(s => s && s.action && s.action.tool === 'Tool_Escalar_Para_Humano');

// Achado real (demanda 297, teste ao vivo): a IA as vezes narra que vai
// "passar pra equipe" sem de fato chamar escalar_para_humano, deixando a
// sessao sem marcar escalada de verdade. Mesmo principio do guardrail de
// valor, aplicado aqui: se o texto soa como promessa de escalar mas nenhuma
// chamada real aconteceu, bloqueia e escala de verdade em vez de deixar a
// promessa vazia sair.
const soaComoEscalar = /passar (pra|para) (minha )?equipe|chamar (a )?equipe|minha equipe (vai|vou)|te passo pra equipe|vou verificar (com|junto)/i.test(texto);
if (soaComoEscalar && !chamouEscalar) {
  return [{ json: {
    ...entrada, guardrail_ok: false,
    motivo_bloqueio: 'texto soa como promessa de escalar pra equipe sem chamada real de escalar_para_humano nesta execucao',
  } }];
}

const valoresNoTexto = extrairValores(texto);

if (valoresNoTexto.length === 0) {
  return [{ json: { ...entrada, guardrail_ok: true, motivo_bloqueio: null } }];
}

// Achado real (demanda 297): tool node invocado pelo AI Agent nao fica
// acessivel via $(nome).all() a partir de um node downstream comum ("No data
// found from `main` input" - o dado do tool call vive na conexao ai_tool, nao
// main). Corrigido usando `returnIntermediateSteps: true` no Agent, que poe o
// trace de chamadas de ferramenta (action.tool + observation) dentro do
// proprio output "main" do Agent, ai sim acessivel normalmente.
const nomesFerramentaValor = [
  'Tool_Consultar_Preco_Produto',
  'Tool_Criar_Pedido_Aguardando_Aprovacao',
  'Tool_Gerar_Cobranca_Pix',
];

let valoresReais = [];
const steps = Array.isArray(entrada._intermediateSteps) ? entrada._intermediateSteps : [];
for (const step of steps) {
  const toolName = step && step.action && step.action.tool;
  if (!nomesFerramentaValor.includes(toolName)) continue;
  let body = step.observation;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { continue; }
  }
  if (!body) continue;
  if (typeof body.valor_final === 'number') valoresReais.push(body.valor_final);
  const frase = body.frase_pronta || '';
  if (frase) valoresReais = valoresReais.concat(extrairValores(frase));
}

const bate = valoresNoTexto.some(v => valoresReais.some(r => Math.abs(r - v) < 0.01));

if (bate) {
  return [{ json: { ...entrada, guardrail_ok: true, motivo_bloqueio: null } }];
}

return [{ json: {
  ...entrada,
  guardrail_ok: false,
  motivo_bloqueio: `valor(es) [${valoresNoTexto.join(', ')}] no texto da IA sem chamada de ferramenta correspondente nesta execucao (ferramentas chamadas: ${steps.map(s => s.action && s.action.tool).join(', ') || 'nenhuma'})`,
} }];

const entrada = $('Guardrail Validacao Saida').first().json;
const resp = $json;
const body = resp.body || {};
return [{ json: {
  telefone: entrada.telefone,
  message_id: entrada.message_id,
  texto_final: body.frase_pronta || 'Chamando a equipe',
  guardrail_bloqueou: true,
  motivo_bloqueio: entrada.motivo_bloqueio,
} }];

const entrada = $json;
return [{ json: {
  telefone: entrada.telefone,
  message_id: entrada.message_id,
  texto_final: entrada.resposta_agente,
  guardrail_bloqueou: false,
  motivo_bloqueio: null,
} }];

const entrada = $json;
const config = $('GET Config Agente').first().json;
return [{ json: {
  telefone: entrada.telefone,
  message_id: entrada.message_id,
  texto_final: entrada.texto_final,
  guardrail_bloqueou: entrada.guardrail_bloqueou,
  motivo_bloqueio: entrada.motivo_bloqueio,
  _zapi_base: config.zapi_url ? config.zapi_url.replace(/\/[^/]+$/, '') : null,
  _zapi_url: config.zapi_url,
  _zapi_token: config.client_token,
} }];

const entrada = $('Montar Envio Z-API').first().json;
const resp = $json;
const body = resp.body || {};
return [{ json: {
  telefone: entrada.telefone,
  message_id: body.messageId || entrada.message_id,
  message_text: entrada.texto_final,
  guardrail_bloqueou: entrada.guardrail_bloqueou,
  motivo_bloqueio: entrada.motivo_bloqueio,
  zaapId: body.zaapId || null,
} }];

const entrada = $('Avaliar Dizu').first().json;
const resp = $json;
const body = resp.body || {};
return [{ json: { ...entrada, is_alto_toque: !!body.is_alto_toque } }];

const entrada = $('Avaliar Alto Toque').first().json;
const resp = $json;
const body = resp.body || {};
return [{ json: {
  telefone: entrada.telefone,
  message_id: entrada.message_id,
  texto_final: body.frase_pronta || 'Chamando a equipe',
  guardrail_bloqueou: false,
  motivo_bloqueio: null,
} }];

// Demanda 321 - Piece 2 (claim): antes de mandar a resposta ja composta pela IA,
// tenta reivindicar o atendimento em jsgrafica_contatos com UPDATE condicional
// (so grava se ninguem mais estiver com o telefone, ou se ja for a propria IA -
// node anterior). Se 0 linhas foram afetadas, um humano assumiu no meio do
// caminho (corrida real entre o gate do workflow 01 e este ponto, tempo de
// resposta do LLM) - a IA NAO manda a resposta que ja tinha preparado. Decisao
// deliberada do dono do negocio, nao e opcional: nunca responder por cima de um
// humano que acabou de assumir.
//
// Mesmo cuidado de formato de resposta do node anterior (httpRequest +
// alwaysOutputData) documentado no workflow 01 (demanda 321) e em 'Detectar Loop
// Resposta Automatica' (307): as vezes 1 item com o array bruto no json, as vezes
// auto-split em 1 item por linha com json vazio {} quando 0 linhas batem. Tratamos
// os dois formatos, sem presumir qual esta ativo.
const items = $input.all();
let rows = [];
for (const it of items) {
  const j = it.json;
  if (Array.isArray(j)) {
    rows = rows.concat(j);
  } else if (j && Object.keys(j).length > 0) {
    rows.push(j);
  }
}
const reivindicado = rows.length > 0;

const entrada = $('Guardrail Falhou?').first().json;

// Demanda 324 (achado real da propria validacao da 323): quando a IA chamou
// escalar_para_humano neste turno, o PATCH acima falha DE PROPOSITO (guarda da
// demanda 323 - nao pode reverter o status_atendimento='escalado' que a
// escalacao real acabou de gravar). Isso NAO e o mesmo caso de 'humano assumiu
// no meio do caminho' - e o resultado esperado da escalacao, e a confirmacao
// 'Chamando a equipe' ainda precisa ser enviada. Detecta via _intermediateSteps
// (mesma tecnica ja usada em 'Guardrail Validacao Saida', mesmo nome de tool
// 'Tool_Escalar_Para_Humano') e forca _reivindicado=true so pra efeito de
// liberar o envio - o PATCH acima continua rodando e continua sem sobrescrever
// o status escalado real, so o resultado dele passa a ser ignorado aqui quando
// a propria IA escalou neste turno.
const chamouEscalar = (entrada._intermediateSteps || [])
  .some(s => s && s.action && s.action.tool === 'Tool_Escalar_Para_Humano');
const _reivindicado = chamouEscalar ? true : reivindicado;

return [{ json: { ...entrada, _reivindicado } }];

const entrada = $json;
return [{ json: {
  telefone: entrada.telefone,
  message_id: entrada.message_id,
  ok: false,
  texto_enviado: null,
  motivo_bloqueio: 'reivindicado_por_humano',
} }];
